import AppKit
// Short procedural paper rustle, generated by Tools/make-paper-sound.py. No external recording.
enum PaperSound {
    static var current:NSSound?
    static func play() {
        guard AppPreferences.defaults.bool(forKey:"paperSound"),let url=Bundle.main.url(forResource:"paper-rustle",withExtension:"wav") else { return }
        current=NSSound(contentsOf:url,byReference:true);current?.volume=0.18;current?.play()
    }
}
